/// Returns the index of the minimal element in `a[lo..]`.
/// 
/// # Panics
/// 
/// Panics if `lo >= a.len()`.
fn find_min(a: &[i32], lo: usize) -> usize {
    assert!(lo < a.len(), "starting index out of bounds");
    let mut min_idx = lo;
    // scan the subarray from lo+1 to end
    for i in (lo + 1)..a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }
    min_idx
}

